   # \'comment\'             : \'## \\a\'         ,  # ??\n            # TOC is automatic\n        },\n        # http://www.pmwiki.org/wiki/PmWiki/TextFormattingRules\n        # http://www.pmwiki.org/wiki/Main/WikiSandbox\n        "pmw": {\n            "title1": "~A~! \\a ",\n            "title2": "~A~!! \\a ",\n            "title3": "~A~!!! \\a ",\n            "title4": "~A~!!!! \\a ",\n            "title5": "~A~!!!!! \\a ",\n            "blockQuoteOpen": "->",\n            "blockQuoteClose": "\\n",\n            # In-text font\n            "fontLargeOpen": "[+",\n            "fontLargeClose": "+]",\n            "fontLargerOpen": "[++",\n            "fontLargerClose": "++]",\n            "fontSmallOpen": "[-",\n            "fontSmallClose": "-]",\n            "fontLargerOpen": "[--",\n            "fontLargerClose": "--]",\n            "fontMonoOpen": "@@",\n            "fontMonoClose": "@@",\n            "fontBoldOpen": "\'\'\'",\n            "fontBoldClose": "\'\'\'",\n            "fontItalicOpen": "\'\'",\n            "fontItalicClose": "\'\'",\n            "fontUnderlineOpen": "{+",\n            "fontUnderlineClose": "+}",\n            "fontStrikeOpen": "{-",\n            "fontStrikeClose": "-}",\n            # Lists\n            "listItemLine": "*",\n            "numlistItemLine": "#",\n            "deflistItem1Open": ": ",\n            "deflistItem1Close": ":",\n            "deflistItem2LineOpen": "::",\n            "deflistItem2LineClose": ":",\n            # Verbatim block\n            "blockVerbOpen": "[@",\n            "blockVerbClose": "@]",\n            "bar1": "----",\n            # URL, email and anchor\n            "url": "\\a",\n            "urlMark": "[[\\a -> \\a]]",\n            "email": "\\a",\n            "emailMark": "[[\\a -> mailto:\\a]]",\n            "anchor": "[[#\\a]]\\n",\n            # Image markup\n            "img": "\\a",\n            #\'imgAlignLeft\'         : \'{{\\a }}\'       ,\n            #\'imgAlignRight\'        : \'{{ \\a}}\'       ,\n            #\'imgAlignCenter\'       : \'{{ \\a }}\'      ,\n            # Table attributes\n            "tableTitleRowOpen": "||! ",\n            "tableTitleRowClose": "||",\n            "tableTitleCellSep": " ||!",\n            "tableRowOpen": "||",\n            "tableRowClose": "||",\n            "tableCellSep": " ||",\n        },\n        # http://en.wikipedia.org/wiki/Help:Editing\n        # http://www.mediawiki.org/wiki/Sandbox\n        "wiki": {\n            "title1": "== \\a ==",\n            "title2": "=== \\a ===",\n            "title3": "==== \\a ====",\n            "title4": "===== \\a =====",\n            "title5": "====== \\a ======",\n            "blockVerbOpen": "<pre>",\n            "blockVerbClose": "</pre>",\n            "blockQuoteOpen": "<blockquote>",\n            "blockQuoteClose": "</blockquote>",\n            "fontMonoOpen": "<tt>",\n            "fontMonoClose": "</tt>",\n            "fontBoldOpen": "\'\'\'",\n            "fontBoldClose": "\'\'\'",\n            "fontItalicOpen": "\'\'",\n            "fontItalicClose": "\'\'",\n            "fontUnderlineOpen": "<u>",\n            "fontUnderlineClose": "</u>",\n            "fontStrikeOpen": "<s>",\n            "fontStrikeClose": "</s>",\n            # XXX Mixed lists not working: *#* list inside numlist inside list\n            "listItemLine": "*",\n            "numlistItemLine": "#",\n            "deflistItem1Open": "; ",\n            "deflistItem2LinePrefix": ": ",\n            "bar1": "----",\n            "url": "[\\a]",\n            "urlMark": "[\\a \\a]",\n            "urlMarkAnchor": "[[\\a|\\a]]",\n            "email": "mailto:\\a",\n            "emailMark": "[mailto:\\a \\a]",\n            # [[Image:foo.png|right|Optional alt/caption text]] (right, left, center, none)\n            "img": "[[Image:\\a~A~]]",\n            "_imgAlignLeft": "|left",\n            "_imgAlignCenter": "|center",\n            "_imgAlignRight": "|right",\n            # {| border="1" cellspacing="0" cellpadding="4" align="center"\n            "tableOpen": "{|~A~~B~",\n            "tableClose": "|}",\n            "tableRowOpen": "|-",\n            "tableTitleRowOpen": "|-",\n            # Note: using one cell per line syntax\n            "tableCellOpen": "\\n|~A~~S~~Z~ ",\n            "tableTitleCellOpen": "\\n!~A~~S~~Z~ ",\n            "_tableBorder": \' border="1"\',\n            "_tableAlignCenter": \' align="center"\',\n            "_tableCellAlignRight": \' align="right"\',\n            "_tableCellAlignCenter": \' align="center"\',\n            "_tableCellColSpan": \' colspan="\\a"\',\n            "_tableAttrDelimiter": " |",\n            "comment": "<!-- \\a -->",\n            "TOC": "__TOC__",\n        },\n        # http://demo.redmine.org/help/wiki_syntax.html\n        # http://demo.redmine.org/help/wiki_syntax_detailed.html\n        # Sandbox: http://demo.redmine.org - create account, add new project\n        "red": {\n            "title1": "h1. \\a",\n            "title2": "h2. \\a",\n            "title3": "h3. \\a",\n            "title4": "h4. \\a",\n            "title5": "h5. \\a",\n            "fontBoldOpen": "*",\n            "fontBoldClose": "*",\n            "fontItalicOpen": "_",\n            "fontItalicClose": "_",\n            "fontStrikeOpen": "-",\n            "fontStrikeClose": "-",\n            "fontUnderlineOpen": "+",\n            "fontUnderlineClose": "+",\n            "blockVerbOpen": "<pre>",\n            "blockVerbClose": "</pre>",\n            "blockQuoteLine": "bq. ",  # XXX It\'s a *paragraph* prefix. (issues 64, 65)\n            "fontMonoOpen": "@",\n            "fontMonoClose": "@",\n            "listItemLine": "*",\n            "numlistItemLine": "#",\n            "deflistItem1Open": "* ",\n            "url": "\\a",\n            "urlMark": \'"\\a":\\a\',  # "Google":http://www.google.com\n            "email": "\\a",\n            "emailMark": \'"\\a":\\a\',\n            "img": "!~A~\\a!",\n            "_imgAlignLeft": "",  # !image.png! (no align == left)\n            "_imgAlignCenter": "=",  # !=image.png!\n            "_imgAlignRight": ">",  # !>image.png!\n            "tableTitleCellOpen": "_.",  # Table header is |_.header|\n            "tableTitleCellSep": "|",\n            "tableCellOpen": "~S~~A~. ",\n            "tableCellSep": "|",\n            "tableRowOpen": "|",\n            "tableRowClose": "|",\n            "_tableCellColSpan": "\\\\\\a",\n            "bar1": "---",\n            "bar2": "---",\n            "TOC": "{{toc}}",\n        },\n        "vimwiki": {\n            "title1": "= \\a =",\n            "title2": "== \\a ==",\n            "title3": "=== \\a ===",\n            "title4": "==== \\a ====",\n            "title5": "===== \\a =====",\n            "blockVerbOpen": "{{{",\n            "blockVerbClose": "}}}",\n            "blockQuoteOpen": "{{{",\n            "blockQuoteClose": "}}}",\n            "fontMonoOpen": "`",\n            "fontMonoClose": "`",\n            "fontBoldOpen": " *",\n            "fontBoldClose": "* ",\n            "fontItalicOpen": " _",\n            "fontItalicClose": "_ ",\n            #\'fontUnderlineOpen\'     : \'<u>\'             ,\n            #\'fontUnderlineClose\'    : \'</u>\'            ,\n            "fontStrikeOpen": " ~~",\n            "fontStrikeClose": "~~ ",\n            "listItemOpen": "- ",\n            "listItemLine": "\\t",\n            "numlistItemOpen": "# ",\n            "numlistItemLine": "\\t",\n            "bar1": "----",\n            "url": "[\\a]",\n            "urlMark": "[\\a \\a]",\n            "email": "mailto:\\a",\n            "emailMark": "[mailto:\\a \\a]",\n            "img": "[\\a]",\n            #\'_imgAlignLeft\'         : \'|left\'           ,\n            #\'_imgAlignCenter\'       : \'|center\'         ,\n            #\'_imgAlignRight\'        : \'|right\'          ,\n            "tableRowOpen": "| ",\n            "tableRowClose": " |",\n            #\'tableTitleRowOpen\'     : \'|-\\n! \'          ,\n  